// Analog pin: A0 on Arduino Uno (ADC range 0-1023, reference 5.0V)
#define RAIN_PIN A0

void setup() {
 Serial.begin(115200);
}

void loop() {
 int raw = analogRead(RAIN_PIN);
 float voltage = raw * 5.0 / 1023.0;

 Serial.print("Rain sensor raw: "); Serial.print(raw);
 Serial.print(" Voltage: "); Serial.print(voltage);
 Serial.println(raw Wet / Rain detected" : " -> Dry"); // lower reading = more water bridging the plates

 delay(500);
}",

